    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: #ffffff;
        --text: #172033;
        --muted: #5f6b85;
        --border: #d9e0ee;
        --border-strong: #95a3bf;
        --brand: #2f6fed;
        --brand-dark: #2357bb;
        --error: #c62828;
        --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(47, 111, 237, 0.14), transparent 42%),
          linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        transform: translateY(-180%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 560px);
        background: var(--surface);
        border: 1px solid rgba(149, 163, 191, 0.2);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 3vw, 2.25rem);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--brand);
      }

      h1 {
        margin: 0;
        font-size: clamp(1.65rem, 4vw, 2.25rem);
        line-height: 1.1;
      }

      .description {
        margin: 0.9rem 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        margin-top: 1.75rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: 1.25rem 1fr;
        gap: 0.75rem;
        align-items: start;
      }

      .checkbox-row input {
        width: 1.125rem;
        height: 1.125rem;
        margin: 0.2rem 0 0;
        accent-color: var(--brand);
      }

      .checkbox-row label {
        font-weight: 600;
        line-height: 1.5;
        cursor: pointer;
      }

      .required {
        color: var(--error);
      }

      .help,
      .error {
        margin: 0;
        padding-left: 2rem;
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .help {
        color: var(--muted);
      }

      .error {
        color: var(--error);
      }

      .actions {
        margin-top: 1.25rem;
        display: flex;
        justify-content: flex-end;
      }

      button[type="submit"] {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(180deg, var(--brand) 0%, var(--brand-dark) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 0.95rem 1.4rem;
        min-height: 3rem;
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(47, 111, 237, 0.25);
