        filter: brightness(1.02);
      }

      button[type="submit"]:focus-visible,
      input[type="checkbox"]:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid rgba(47, 111, 237, 0.35);
        outline-offset: 3px;
      }

      [hidden] {
        display: none !important;
      }

      @media (max-width: 420px) {
        .card {
          padding: 1.25rem;
