     <main id="maincontent" tabindex="-1"></main>

     <script>
       const h = (tag, attrs = {}, children = "") => {
         const attrString = Object.entries(attrs)
           .filter(([, value]) => value !== false && value != null)
           .map(([name, value]) => {
             if (value === true) return ` ${name}`;
             return ` ${name}="${String(value).replace(/"/g, "&quot;")}"`;
           })
           .join("");

         const content = Array.isArray(children) ? children.join("") : children;
         return `<${tag}${attrString}>${content}</${tag}>`;
       };

       const App = () => {
         return [
           h("section", { class: "card", "aria-labelledby": "page-title" }, [
             h("p", { class: "eyebrow" }, "Terms of use"),
             h("h1", { id: "page-title" }, "Confirm your consent"),
             h(
               "p",
               { class: "description" },
               "Review the terms and agree below to continue."
             ),
             h("form", { id: "consent-form", novalidate: "" }, [
               h("div", { class: "form-field" }, [
                 h("div", { class: "checkbox-row" }, [
                   h("input", {
                     id: "agree-terms",
                     name: "agreeTerms",
                     type: "checkbox",
                     required: "",
                     "aria-describedby": "agree-help"
                   }),
                   h("label", { for: "agree-terms" }, [
                     "I agree to the terms of use ",
                     h("span", { class: "required", "aria-hidden": "true" }, "*")
                   ])
                 ]),
                 h(
                   "p",
                   { class: "help", id: "agree-help" },
                   "Required to proceed with your account setup."
                 ),
                 h(
                   "p",
                   { class: "error", id: "agree-error", hidden: "" },
                   "Error: Please agree to the terms of use."
                 )
               ]),
               h("div", { class: "actions" }, [
                 h("button", { type: "submit" }, "Continue")
               ])
             ])
           ])
         ].join("");
       };

       document.querySelector("main").innerHTML = App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("agree-terms");
       const error = document.getElementById("agree-error");

       const syncValidity = (showError) => {
         const invalid = !checkbox.checked;
         if (invalid && showError) {
           checkbox.setAttribute("aria-invalid", "true");
           checkbox.setAttribute("aria-describedby", "agree-help agree-error");
           error.hidden = false;
           return;
         }

         checkbox.removeAttribute("aria-invalid");
         checkbox.setAttribute("aria-describedby", "agree-help");
         error.hidden = true;
       };

       checkbox.addEventListener("change", () => syncValidity(false));

       form.addEventListener("submit", (event) => {
         if (!checkbox.checkValidity()) {
           event.preventDefault();
           syncValidity(true);
           checkbox.focus();
           return;
         }

         event.preventDefault();
         syncValidity(false);
       });

       syncValidity(false);
     </script>
